let commandIndex=[];
async function buildSearchIndex(){const m=new Map;const add=(title,href,group='Site',keywords='')=>{const k=`${title}|${href}`;if(!m.has(k))m.set(k,{title,href,group,keywords})};STATIC_INDEX.forEach(x=>add(...x));qsa('a[href]').forEach(a=>{const t=(a.textContent||'').trim();const href=a.getAttribute('href');if(t&&href&&!href.startsWith('#')&&!href.startsWith('javascript:'))add(t,href,'This page')});try{const sb=await getSB();if(sb){const [cat,tools,help,forums]=await Promise.allSettled([sb.from('catalog_products').select('product_code,title,short_title').eq('active',true).limit(80),sb.from('platform_tools').select('tool_code,name,href').eq('active',true).limit(100),sb.from('help_articles').select('title,slug,category').eq('status','published').limit(100),sb.from('commons_forums').select('forum_code,name,section_name').eq('active',true).limit(100)]);(cat.value?.data||[]).forEach(x=>add(x.short_title||x.title,`store.html?product=${encodeURIComponent(x.product_code)}`,'Books',x.title));(tools.value?.data||[]).forEach(x=>add(x.name,x.href||'tools.html','Tools',x.tool_code));(help.value?.data||[]).forEach(x=>add(x.title,`help.html#${encodeURIComponent(x.slug||'')}`,'Documentation',x.category));(forums.value?.data||[]).forEach(x=>add(x.name,`market-commons.html?forum=${encodeURIComponent(x.forum_code)}`,'Market Commons',x.section_name))}}
 catch{}commandIndex=[...m.values()];return commandIndex}
function commandPalette(){if(qs('#fe-command'))return;const d=document.createElement('dialog');d.id='fe-command';d.className='fe-dialog';d.innerHTML='<div class="fe-dialog-head"><h2>Search & Commands</h2><button class="fe-dialog-close" aria-label="Close">×</button></div><div class="fe-dialog-body"><input class="fe-command-input" type="search" autocomplete="off" placeholder="Search books, Labs, tools, help, pages…" aria-label="Search site"><div class="fe-command-results"></div></div>';document.body.appendChild(d);const input=qs('input',d),results=qs('.fe-command-results',d);const render=()=>{const q=input.value.trim().toLowerCase();const arr=(commandIndex.length?commandIndex:STATIC_INDEX.map(([title,href,group])=>({title,href,group}))).filter(x=>!q||`${x.title} ${x.group} ${x.keywords||''}`.toLowerCase().includes(q)).slice(0,24);results.innerHTML=arr.length?arr.map((x,i)=>`<a class="fe-command-item ${i===0?'active':''}" href="${esc(x.href)}"><span><strong>${esc(x.title)}</strong><small>${esc(x.group||'Site')}</small></span><span>↵</span></a>`).join(''):'<div class="fe-command-empty">No matching destination.</div>'};input.oninput=render;input.onkeydown=e=>{const items=qsa('.fe-command-item',results);if(!items.length)return;let i=items.findIndex(x=>x.classList.contains('active'));if(e.key==='ArrowDown'){e.preventDefault();items[i]?.classList.remove('active');i=(i+1)%items.length;items[i].classList.add('active');items[i].scrollIntoView({block:'nearest'})}else if(e.key==='ArrowUp'){e.preventDefault();items[i]?.classList.remove('active');i=(i-1+items.length)%items.length;items[i].classList.add('active');items[i].scrollIntoView({block:'nearest'})}else if(e.key==='Enter'){e.preventDefault();items[Math.max(0,i)]?.click()}};qs('.fe-dialog-close',d).onclick=()=>d.close();d.addEventListener('close',()=>input.value='');window.SiteUI.openCommand=async()=>{if(!commandIndex.length)await buildSearchIndex();render();d.showModal();setTimeout(()=>input.focus(),30)};document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();window.SiteUI.openCommand()}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)){e.preventDefault();window.SiteUI.openCommand()}})}
// v0.14.0.12: One Alerts surface for personal notifications and scheduled site announcements.
let alertRefreshTimer=null;
async function fetchAlertData(){
 const session=await getSession();const headers=session?{authorization:`Bearer ${session.access_token}`}:{},jobs=[fetch('/api/site-announcements',{headers,cache:'no-store'}).then(async r=>{if(!r.ok)throw Error('Announcements unavailable');return r.json()})];
 if(session)jobs.push(uiApi('notifications'));
 const settled=await Promise.allSettled(jobs);
 const announcements=settled[0].status==='fulfilled'&&settled[0].value.ok?settled[0].value.announcements||[]:[];
 const notifications=session&&settled[1]?.status==='fulfilled'?settled[1].value.notifications||[]:[];
 return {announcements,notifications,session,announcementFailed:settled[0].status==='rejected',notificationFailed:!!session&&settled[1]?.status==='rejected'};
}
function seenAnnouncementKey(session){return `alerts-seen-announcements:${session?.user?.id||'public'}`}
function seenAnnouncements(session){return new Set(local.get(seenAnnouncementKey(session),[]))}
function markAnnouncementsSeen(session,items){const ids=[...seenAnnouncements(session),...items.map(x=>String(x.id))];local.set(seenAnnouncementKey(session),[...new Set(ids)].slice(-300))}
function headerUtilities(){
 const nav=qs('header .nav,header .wrap.nav');if(!nav)return;
 let host=qs('.fe-header-tools',nav);
 if(!host){host=document.createElement('div');host.className='fe-header-tools';host.style.display='flex';host.style.gap='.4rem';host.style.alignItems='center';host.innerHTML='<button class="fe-command-button" type="button" aria-label="Search"><span>Search</span><kbd>Ctrl K</kbd></button>';nav.appendChild(host);qs('.fe-command-button',host).onclick=()=>window.SiteUI.openCommand?.()}
 if(!qs('.fe-notify-button',host)){
  const b=document.createElement('button');b.className='fe-notify-button';b.type='button';b.setAttribute('aria-label','Alerts: notifications and announcements');b.innerHTML='<span aria-hidden="true">●</span><span>Alerts</span><span class="fe-notify-count" hidden>0</span>';
  host.appendChild(b);b.onclick=openNotifications;loadNotificationCount(b);
  if(!alertRefreshTimer)alertRefreshTimer=setInterval(()=>{if(!document.hidden)loadNotificationCount(b)},60000);
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)loadNotificationCount(b)});
 }
}
async function loadNotificationCount(btn){
 try{const data=await fetchAlertData(),seen=seenAnnouncements(data.session);
  const unread=(data.notifications||[]).filter(x=>!x.is_read).length+(data.announcements||[]).filter(x=>!seen.has(String(x.id))).length;
  const count=qs('.fe-notify-count',btn);if(count){count.textContent=String(unread);count.hidden=!unread}
 }catch{/* Keep Alerts available; count is a nonessential enhancement. */}
}
async function openNotifications(){
 let d=qs('#fe-notifications');if(!d){d=document.createElement('dialog');d.id='fe-notifications';d.className='fe-dialog fe-drawer';d.innerHTML='<div class="fe-dialog-head"><h2>Alerts</h2><button class="fe-dialog-close" aria-label="Close">×</button></div><div class="fe-dialog-body"><div class="fe-notification-list" aria-live="polite"><div class="fe-state">Loading alerts…</div></div></div>';document.body.appendChild(d);qs('.fe-dialog-close',d).onclick=()=>d.close()}
 if(!d.open)d.showModal();const host=qs('.fe-notification-list',d);host.innerHTML='<div class="fe-state">Loading alerts…</div>';
 try{
  const data=await fetchAlertData();const seen=seenAnnouncements(data.session);
  const anns=data.announcements||[],notes=data.notifications||[];
  const annSection=`<section class="gu-alerts-section"><h3>Site Announcements <small>(${anns.length})</small></h3>${data.announcementFailed?'<p class="gu-alerts-status">Announcements could not be loaded. Try again.</p>':anns.length?anns.map(a=>`<article class="gu-alert-announcement ${seen.has(String(a.id))?'seen':''}"><strong>${esc(a.title)}</strong><p>${esc(a.body||'')}</p><span class="gu-alerts-meta">${esc((a.announcement_type||'info').toUpperCase())}</span></article>`).join(''):'<p class="gu-alerts-empty">No active site announcements.</p>'}</section>`;
  const personalSection=`<section class="gu-alerts-section"><h3>Your Notifications <small>(${notes.length})</small></h3>${data.notificationFailed?'<p class="gu-alerts-status">Notifications could not be loaded. Try again.</p>':notes.length?notes.map(n=>`<article class="fe-notification ${n.is_read?'':'unread'}"><h4>${esc(n.title)}</h4><p>${esc(n.body||'')}</p><time>${Number.isFinite(Date.parse(n.created_at))?new Date(n.created_at).toLocaleString():''}</time>${n.href&&/^\/(?!\/)|^[a-z0-9_-]+\.html(?:[?#].*)?$/i.test(n.href)?`<div><a href="${esc(n.href)}">Open</a></div>`:''}</article>`).join(''):'<p class="gu-alerts-empty">No personal notifications.</p>'}</section>`;
  host.innerHTML=annSection+(data.session?personalSection:'<p class="gu-alerts-meta">Sign in to view account notifications.</p>');
  markAnnouncementsSeen(data.session,anns);
  const unread=notes.filter(x=>!x.is_read).map(x=>x.id);
  if(unread.length)uiApi('notifications_read',{method:'POST',body:{ids:unread}}).catch(()=>{});
  const b=qs('.fe-notify-button');if(b)loadNotificationCount(b);
 }catch(e){host.innerHTML=`<div class="fe-state error"><h3>Alerts unavailable</h3><p>${esc(e.message)}</p><button class="btn" type="button" data-retry>Retry</button></div>`;qs('[data-retry]',host)?.addEventListener('click',()=>{if(d.open)d.close();openNotifications()})}
}
async function recordVisit(){const title=(document.title||qs('h1')?.textContent||path).split('|')[0].trim();const item={title,href:location.pathname+location.search,at:new Date().toISOString(),type:'page'};let recent=local.get('recent',[]).filter(x=>x.href!==item.href);recent.unshift(item);local.set('recent',recent.slice(0,20));const s=await getSession();if(s)uiApi('activity_add',{method:'POST',body:{activityType:'page_view',title,href:item.href,metadata:{path}}}).catch(()=>{})}
async function bookmarks(){const s=await getSession();if(s)try{return (await uiApi('bookmarks')).bookmarks||[]}catch{}return local.get('bookmarks',[])}
async function toggleBookmark(item){const s=await getSession();if(s){const j=await uiApi('bookmark_toggle',{method:'POST',body:item});toast(j.saved?'Saved to favorites.':'Removed from favorites.',j.saved?'ok':'info');return j.saved}let b=local.get('bookmarks',[]),i=b.findIndex(x=>x.item_key===item.itemKey);let saved;if(i>=0){b.splice(i,1);saved=false}else{b.unshift({item_key:item.itemKey,title:item.title,href:item.href,item_type:item.itemType||'page',created_at:new Date().toISOString()});saved=true}local.set('bookmarks',b);toast(saved?'Saved to favorites.':'Removed from favorites.',saved?'ok':'info');return saved}
function bookmarkButton(){if(/\/(signin|create-account|admin|checkout)(\.html)?$/.test(path))return;const title=(qs('h1')?.textContent||document.title).trim();if(!title)return;const item={itemType:path.includes('lab')?'lab':path.includes('market-commons')?'discussion':path.includes('help')?'documentation':'page',itemKey:location.pathname+location.search,title,href:location.pathname+location.search};const b=document.createElement('button');b.className='fe-bookmark-floating';b.type='button';b.textContent='☆ Save';b.title='Save to favorites';document.body.appendChild(b);bookmarks().then(xs=>{const saved=xs.some(x=>(x.item_key||x.itemKey)===item.itemKey);b.classList.toggle('saved',saved);b.textContent=saved?'★ Saved':'☆ Save'});b.onclick=async()=>{const saved=await toggleBookmark(item);b.classList.toggle('saved',saved);b.textContent=saved?'★ Saved':'☆ Save'}}

function formDirtyProtection(){let dirty=false;const targets=/\/(journal-entry|lab-player|admin|market-commons|settings)(\.html)?/.test(path);if(!targets)return;document.addEventListener('input',e=>{if(e.target.matches('input,textarea,select'))dirty=true},true);document.addEventListener('submit',()=>dirty=false,true);document.addEventListener('click',e=>{if(e.target.closest('[data-save],#admin-dialog-save,#v11-modal-save,.btn[type="submit"]'))setTimeout(()=>dirty=false,400)},true);window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});window.SiteUI.setClean=()=>dirty=false}
function autosaveDrafts(){if(!/\/(journal-entry|lab-player|market-commons)(\.html)?/.test(path))return;qsa('textarea').forEach((t,i)=>{if(t.dataset.feAutosave)return;t.dataset.feAutosave='1';const k=`draft:${location.pathname}:${t.id||t.name||i}`;const v=local.get(k,'');if(!t.value&&v)t.value=v;let timer;t.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>{local.set(k,t.value);let n=t.parentElement?.querySelector('.fe-autosave-note');if(!n){n=document.createElement('small');n.className='fe-autosave-note fe-muted';t.after(n)}n.textContent=`Saved locally ${new Date().toLocaleTimeString()}`},350)});t.form?.addEventListener('submit',()=>local.del(k))})}

