 const pw=qsa('input[type="password"]',form);pw.forEach(input=>{if(input.dataset.feCaps)return;input.dataset.feCaps='1';const n=document.createElement('div');n.className='fe-caps-note';n.hidden=true;n.textContent='Caps Lock is on.';input.insertAdjacentElement('afterend',n);input.addEventListener('keyup',e=>{n.hidden=!e.getModifierState?.('CapsLock')});input.addEventListener('keydown',e=>{n.hidden=!e.getModifierState?.('CapsLock')})});
 if(path.includes('create-account')){const p=pw[0];if(p&&!qs('.fe-password-meter',p.parentElement)){const m=document.createElement('div');m.className='fe-password-meter';m.innerHTML='<span></span>';const note=document.createElement('div');note.className='fe-password-note';note.textContent='Use 12+ characters with a mix of character types.';p.insertAdjacentElement('afterend',note);note.insertAdjacentElement('beforebegin',m);p.addEventListener('input',()=>{let s=0,v=p.value;if(v.length>=8)s++;if(v.length>=12)s++;if(/[A-Z]/.test(v)&&/[a-z]/.test(v)&&/\d/.test(v))s++;if(/[^A-Za-z0-9]/.test(v))s++;m.dataset.score=String(s);note.textContent=s>=4?'Strong password.':s>=3?'Good password; longer is better.':s>=2?'Fair; add length and variety.':'Use 12+ characters with a mix of character types.'})}}
