async function securityCenter(host){try{const sb=await getSB(),ses=await getSession();if(!sb||!ses)throw new Error('Not signed in');const u=ses.user;let timeout='30';try{const {data}=await sb.from('profiles').select('session_timeout_minutes').eq('id',u.id).maybeSingle();timeout=String(data?.session_timeout_minutes||30)}catch{}host.innerHTML=`<div class="fe-security-item"><strong>Email verification</strong><div>${u.email_confirmed_at?'Verified':'Not verified'}</div></div><div class="fe-security-item"><strong>Last sign in</strong><div>${u.last_sign_in_at?new Date(u.last_sign_in_at).toLocaleString():'Unavailable'}</div></div><div class="fe-security-item"><strong>Automatic sign-out</strong><div>${esc(timeout)} minutes</div></div><div class="fe-security-item"><strong>Connected credentials</strong><div>Managed under Connections & API Keys</div></div>`}catch(e){host.innerHTML=`<div class="fe-state error">${esc(e.message)}</div>`}}
