function sessionWarning(){getSession().then(async ses=>{if(!ses)return;let mins=30;try{const sb=await getSB(),{data}=await sb.from('profiles').select('session_timeout_minutes').eq('id',ses.user.id).maybeSingle();mins=Number(data?.session_timeout_minutes||30)}catch{}if(!mins||mins>=1440)return;let last=Date.now(),shown=false;const touch=()=>{last=Date.now();shown=false};['pointerdown','keydown','scroll'].forEach(e=>addEventListener(e,touch,{passive:true}));setInterval(async()=>{const remain=mins*60000-(Date.now()-last);if(remain<=120000&&remain>0&&!shown){shown=true;const ok=await confirmDialog({title:'Session expiring soon',message:`Your session will expire in about ${Math.max(1,Math.ceil(remain/60000))} minute(s). Stay signed in?`,confirmText:'Stay signed in'});if(ok){try{const sb=await getSB();await sb.auth.refreshSession();touch();toast('Session extended.','ok')}catch{}}}},15000)})}

