function convertCheckboxes(root){qsa('input[type="checkbox"]',root).forEach(input=>{if(input.dataset.feSwitch)return;input.dataset.feSwitch='1';const label=input.closest('label');if(!label)return;const text=[...label.childNodes].filter(n=>n.nodeType===3).map(n=>n.textContent).join(' ').trim()||label.textContent.replace(input.value||'','').trim();label.classList.add('fe-switch-row');label.innerHTML='';const copy=document.createElement('span');copy.className='fe-switch-copy';copy.innerHTML=`<strong>${esc(text||input.dataset.k||'Option')}</strong><small>${esc(switchHelp(text||input.dataset.k||''))}</small>`;const sw=document.createElement('span');sw.className='fe-switch';sw.appendChild(input);const track=document.createElement('span');track.className='fe-switch-track';const state=document.createElement('span');state.className='fe-switch-state';const update=()=>state.textContent=input.checked?'Enabled':'Disabled';update();input.addEventListener('change',update);sw.append(track,state);label.append(copy,sw)})}
function switchHelp(name){const s=name.toLowerCase();if(s.includes('kdp'))return 'When enabled, direct digital website sales are locked for this title.';if(s.includes('direct digital'))return 'Website digital delivery. Available only when KDP Select is off.';if(s.includes('active'))return 'Controls whether this record participates in the live platform.';if(s.includes('public'))return 'Controls whether customers can see this item.';if(s.includes('companion'))return 'Controls companion learning access for this book.';if(s.includes('ad'))return 'Controls sponsor visibility for this access level.';return 'Slide right to enable; left to disable.'}
function tabifyForm(grid){if(grid.classList.contains('fe-tabbed'))return;grid.classList.add('fe-tabbed');const fields=[...grid.children];if(fields.length<8)return;const sections={Basics:[],Publication:[],Channels:[],Access:[],Visibility:[],Advanced:[]};fields.forEach(f=>{const t=f.textContent.toLowerCase();let k='Basics';if(/publication|release|edition|kdp/.test(t))k='Publication';else if(/amazon|checkout|direct|lemon|url/.test(t))k='Channels';else if(/companion|trial|lifetime|book key/.test(t))k='Access';else if(/active|public|visible|status/.test(t))k='Visibility';else if(/metadata|sort|code|slug/.test(t))k='Advanced';sections[k].push(f)});const tabs=document.createElement('div');tabs.className='fe-form-tabs';grid.before(tabs);Object.entries(sections).filter(([,arr])=>arr.length).forEach(([name,arr],i)=>{const b=document.createElement('button');b.type='button';b.textContent=name;b.classList.toggle('active',i===0);tabs.appendChild(b);arr.forEach(f=>{f.dataset.fePane=name;f.classList.toggle('fe-form-pane',true);f.classList.toggle('active',i===0);if(f.querySelector('textarea'))f.classList.add('fe-field-wide')});b.onclick=()=>{qsa('button',tabs).forEach(x=>x.classList.toggle('active',x===b));fields.forEach(f=>f.classList.toggle('active',f.dataset.fePane===name))}})}
function dependencyRules(root){const byLabel=s=>qsa('label',root).find(l=>l.textContent.toLowerCase().includes(s));const k=byLabel('kdp select')?.querySelector('input[type="checkbox"]'),d=byLabel('direct digital')?.querySelector('input[type="checkbox"]');if(!k||!d)return;const apply=()=>{if(k.checked){d.checked=false;d.disabled=true;d.closest('.fe-switch-row')?.classList.add('fe-locked');d.closest('.fe-switch-row')?.querySelector('.fe-switch-state')&&(d.closest('.fe-switch-row').querySelector('.fe-switch-state').textContent='Locked')}else{d.disabled=false;d.closest('.fe-switch-row')?.classList.remove('fe-locked')}};k.addEventListener('change',apply);apply()}

